'use client';

import React, { useState } from 'react';
import { supabase } from '../../src/lib/supabaseClient';
import { isValidRut, formatRut } from '../../src/lib/rut';
import { CartItem } from '../page';
import styles from './AppLayout.module.css';

interface CheckoutModalProps {
  cartItems: CartItem[];
  total: number;
  onClose: () => void;
  onOrderSuccess: () => void;
}

const formatCLP = (value: number) =>
  new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP' }).format(value);

function buildWhatsAppMessage(
  items: CartItem[],
  total: number,
  name: string,
  rut: string,
  deliveryType: 'delivery' | 'retiro',
  address: string,
  notes: string
): string {
  const lines: string[] = [];
  lines.push('🛒 *Nuevo Pedido - Semillas de Familia*');
  lines.push('');
  lines.push(`*Cliente:* ${name}`);
  lines.push(`*RUT:* ${rut}`);
  lines.push(`*Entrega:* ${deliveryType === 'delivery' ? 'Despacho a domicilio' : 'Retiro en tienda'}`);
  if (deliveryType === 'delivery' && address) {
    lines.push(`*Dirección:* ${address}`);
  }
  lines.push('');
  lines.push('*Productos:*');
  items.forEach((item) => {
    lines.push(`- ${item.quantity}x ${item.title} — ${formatCLP(item.final_price * item.quantity)}`);
  });
  lines.push('');
  lines.push(`*Total: ${formatCLP(total)}*`);
  if (notes.trim()) {
    lines.push('');
    lines.push(`*Notas:* ${notes.trim()}`);
  }
  return lines.join('\n');
}

export default function CheckoutModal({ cartItems, total, onClose, onOrderSuccess }: CheckoutModalProps) {
  const [name, setName] = useState('');
  const [rut, setRut] = useState('');
  const [deliveryType, setDeliveryType] = useState<'delivery' | 'retiro'>('retiro');
  const [address, setAddress] = useState('');
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!name.trim()) {
      setError('Ingresa tu nombre.');
      return;
    }
    if (!isValidRut(rut)) {
      setError('El RUT ingresado no es válido.');
      return;
    }
    if (deliveryType === 'delivery' && !address.trim()) {
      setError('Ingresa la dirección de despacho.');
      return;
    }

    const whatsappNumber = process.env.NEXT_PUBLIC_WHATSAPP_NUMBER;
    if (!whatsappNumber) {
      setError('El número de WhatsApp de la tienda no está configurado todavía. Contacta al administrador.');
      return;
    }

    setSubmitting(true);

    const formattedRut = formatRut(rut);

    const { data: order, error: orderError } = await supabase
      .from('orders')
      .insert({
        customer_name: name.trim(),
        rut: formattedRut,
        delivery_type: deliveryType,
        delivery_address: deliveryType === 'delivery' ? address.trim() : null,
        notes: notes.trim() || null,
        total,
        status: 'pendiente',
      })
      .select()
      .single();

    if (orderError || !order) {
      setSubmitting(false);
      setError('No se pudo registrar el pedido. Intenta de nuevo.');
      return;
    }

    const itemsPayload = cartItems.map((item) => ({
      order_id: order.id,
      product_id: item.id,
      product_title: item.title,
      quantity: item.quantity,
      unit_price: item.final_price,
    }));

    const { error: itemsError } = await supabase.from('order_items').insert(itemsPayload);

    setSubmitting(false);

    if (itemsError) {
      setError('El pedido se creó pero hubo un problema al guardar los productos. Contacta a la tienda.');
      return;
    }

    const message = buildWhatsAppMessage(cartItems, total, name.trim(), formattedRut, deliveryType, address, notes);
    const waUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
    window.open(waUrl, '_blank');

    onOrderSuccess();
  };

  return (
    <div className={styles.sidebarOverlay + ' ' + styles.isOpen} style={{ zIndex: 150 }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          position: 'fixed',
          top: 0,
          right: 0,
          bottom: 0,
          width: '100%',
          maxWidth: 420,
          background: '#fdfcf1',
          zIndex: 151,
          overflowY: 'auto',
          padding: '1.75rem 1.5rem',
        }}
      >
        <div className={styles.sidebarHeader}>
          <h3>Finalizar Pedido</h3>
          <button className={styles.closeBtn} onClick={onClose}>
            ✕
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', fontSize: '0.8rem', fontWeight: 700, marginBottom: '0.4rem' }}>
              Nombre completo
            </label>
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              style={inputStyle}
              required
            />
          </div>

          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', fontSize: '0.8rem', fontWeight: 700, marginBottom: '0.4rem' }}>
              RUT
            </label>
            <input
              value={rut}
              onChange={(e) => setRut(e.target.value)}
              placeholder="12345678-9"
              style={inputStyle}
              required
            />
          </div>

          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', fontSize: '0.8rem', fontWeight: 700, marginBottom: '0.4rem' }}>
              Entrega
            </label>
            <div style={{ display: 'flex', gap: '0.75rem' }}>
              <button
                type="button"
                onClick={() => setDeliveryType('retiro')}
                style={{
                  ...toggleBtnStyle,
                  ...(deliveryType === 'retiro' ? toggleBtnActiveStyle : {}),
                }}
              >
                Retiro en tienda
              </button>
              <button
                type="button"
                onClick={() => setDeliveryType('delivery')}
                style={{
                  ...toggleBtnStyle,
                  ...(deliveryType === 'delivery' ? toggleBtnActiveStyle : {}),
                }}
              >
                Despacho
              </button>
            </div>
          </div>

          {deliveryType === 'delivery' && (
            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', fontSize: '0.8rem', fontWeight: 700, marginBottom: '0.4rem' }}>
                Dirección de despacho
              </label>
              <input
                value={address}
                onChange={(e) => setAddress(e.target.value)}
                style={inputStyle}
                required
              />
            </div>
          )}

          <div style={{ marginBottom: '1.25rem' }}>
            <label style={{ display: 'block', fontSize: '0.8rem', fontWeight: 700, marginBottom: '0.4rem' }}>
              Notas del pedido (opcional)
            </label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={3}
              placeholder="Ej: entregar después de las 18:00"
              style={{ ...inputStyle, resize: 'vertical' }}
            />
          </div>

          <div
            style={{
              background: '#ffffff',
              border: '1px solid rgba(0,0,0,0.08)',
              borderRadius: '0.85rem',
              padding: '1rem',
              marginBottom: '1.25rem',
            }}
          >
            {cartItems.map((item) => (
              <div
                key={item.id}
                style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', marginBottom: '0.4rem' }}
              >
                <span>{item.quantity}x {item.title}</span>
                <span>{formatCLP(item.final_price * item.quantity)}</span>
              </div>
            ))}
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                fontWeight: 800,
                fontSize: '1.05rem',
                marginTop: '0.6rem',
                paddingTop: '0.6rem',
                borderTop: '1px solid #f1f5f9',
              }}
            >
              <span>Total</span>
              <span style={{ color: '#15803d' }}>{formatCLP(total)}</span>
            </div>
          </div>

          {error && <p style={{ color: '#ef4444', fontSize: '0.85rem', marginBottom: '1rem' }}>{error}</p>}

          <button type="submit" className={styles.cartCheckoutBtn} disabled={submitting}>
            {submitting ? 'Enviando...' : 'Enviar Pedido por WhatsApp'}
          </button>
        </form>
      </div>
    </div>
  );
}

const inputStyle: React.CSSProperties = {
  width: '100%',
  padding: '0.7rem 0.85rem',
  borderRadius: '0.65rem',
  border: '1px solid #e2e8f0',
  fontSize: '0.9rem',
  background: '#ffffff',
};

const toggleBtnStyle: React.CSSProperties = {
  flex: 1,
  padding: '0.65rem',
  borderRadius: '0.65rem',
  border: '1px solid #e2e8f0',
  background: '#ffffff',
  color: '#57534e',
  fontWeight: 600,
  fontSize: '0.85rem',
  cursor: 'pointer',
};

const toggleBtnActiveStyle: React.CSSProperties = {
  background: '#1c1917',
  color: '#ffffff',
  borderColor: '#1c1917',
};